import{_ as t,o as e,c as _,a3 as o}from"./chunks/framework.DdpBa4_E.js";const s="/ReadBooks/assets/image-020.uBvP27FO.jpg",p="/ReadBooks/assets/image-021.DOeHESCO.jpg",f=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/attached/43-和安全型的人交往，又有什么不同呢？.md","filePath":"books/attached/43-和安全型的人交往，又有什么不同呢？.md","lastUpdated":1794298621000}'),r={name:"books/attached/43-和安全型的人交往，又有什么不同呢？.md"};function d(i,a,n,c,l,m){return e(),_("div",null,[...a[0]||(a[0]=[o('<h3 id="和安全型的人交往-又有什么不同呢" tabindex="-1">和安全型的人交往，又有什么不同呢？ <a class="header-anchor" href="#和安全型的人交往-又有什么不同呢" aria-label="Permalink to &quot;和安全型的人交往，又有什么不同呢？&quot;">​</a></h3><p>接着我们就来说说，假使你成了上述大概率事件之外的一员，遇到了一个安全型伴侣，又会有什么不同呢？你是不是有种挖到金矿的感觉，又或者让幸福转瞬即逝了？</p><p>几年前，蕾切尔就准备把她的邻居蔻依（Chloe）和朋友特雷弗（Trevor）撮合到一起，特雷弗可是个典型的安全型伴侣。特雷弗在医学院念书时，刚从一段十多年的感情中结束，希望寻找一段新的恋情。他和前女友从18岁相恋到28岁分手，即使女友百般挑剔，他也未曾想过分手；但最终女友还是离他而去了。特雷弗为此难过了很久，但还是决定迎接新的生活。特雷弗是个长相帅气、幽默风趣的小伙子，同时也是个运动健将。不仅如此，他意志坚定，性格稳重，家境优渥，涵养良好，所有的这些特质，都描绘了一位完美伴侣，不是吗？</p><p>别想的那么简单。蔻依一见到特雷弗，很快就表示丧失了兴趣。她承认特雷弗长相帅气，甚至有点儿性感，但是却“并不来电”。这让蕾切尔非常疑惑，她实在想不通蔻依为什么没看上特雷弗。</p><p>再往深入地理解，我们就会明白：作为一个焦虑型的人，你在遇到安全型伴侣之后，产生的感受是与回避型截然相反的。安全型依恋风格的人，传达出来的信息都是很坦诚、直率并且始终如一的。安全型的人不排斥亲密，也相信自己值得被爱。他们并不需要时时旁敲侧击或不择手段。同时，他们的困惑也会明确表达，不需要通过发脾气和猜疑来表现。因此，就你自己来说，依恋机制会相对比较平和。可是，由于你已经习惯了在爱情中触发依恋机制，而安全型伴侣不会让你有拉响警报的机会，因此你便很难对他们心动。你已经将平静的依恋机制，等同于无趣和冷漠，而正是基于这个谬论，你往往会让完美的伴侣就此流走。</p><p>蔻依在面对特雷弗时产生如此不好的体验，正是由于她将依恋机制的触发，看作为爱情的必需品。最终与她成婚的托尼，一开始看起来非常自信而有魅力，却常常不失时机地令她心绪难平。</p><p>不过所幸，特雷弗和蔻依最后的归宿都还不赖。特雷弗也没有孑然一身太久，很快就找到了不错的伴侣，至今依然生活甜蜜。他们一起周游世界，婚姻美满并有了小孩。特雷弗的确是个很好的父亲和丈夫人选。相比之下，蔻依的经历要辗转一些。不过在与托尼痛苦地相爱相杀几年以后，她终于算是开窍了，认识到了与一位安全型伴侣，开始稳定的恋爱是件多么美好的事情。她与托尼离婚以后遇到了布鲁斯，这个男人和特雷弗一样，对她关怀备至。</p><p>其实每个人都能够获得这样的美好结局，而且这样的幸福并非可遇不可求。诀窍在于，不要太过自负或是妄自菲薄，更不要陷入将恋爱的激情混淆于触发的依恋机制。总之，切忌让情感的无效性一直困扰着你。</p><p>若你是焦虑型，与安全型恋人交往是最佳选择，原因如下：</p><p><img src="'+s+'" alt="" loading="lazy"></p><p><img src="'+p+'" alt="" loading="lazy"></p>',11)])])}const g=t(r,[["render",d]]);export{f as __pageData,g as default};
